CREATE TABLE "roles" ("id" character varying(36) NOT NULL, "createdAt" TIMESTAMP NOT NULL DEFAULT now(), "updatedAt" TIMESTAMP NOT NULL DEFAULT now(), "name" character varying(80) NOT NULL, "permissions" json NOT NULL, CONSTRAINT "UQ_648e3f5447f725579d7d4ffdfb7" UNIQUE ("name"), CONSTRAINT "PK_c1433d71a4838793a49dcad46ab" PRIMARY KEY ("id"));
CREATE TABLE "users" ("id" character varying(36) NOT NULL, "createdAt" TIMESTAMP NOT NULL DEFAULT now(), "updatedAt" TIMESTAMP NOT NULL DEFAULT now(), "email" character varying(254) NOT NULL, "displayName" character varying(120) NOT NULL, "roleId" character varying(36) NOT NULL, "active" boolean NOT NULL DEFAULT true, CONSTRAINT "UQ_97672ac88f789774dd47f7c8be3" UNIQUE ("email"), CONSTRAINT "PK_a3ffb1c0c8416b9fc6f907b7433" PRIMARY KEY ("id"));
CREATE TABLE "cms_attachments" ("id" character varying(36) NOT NULL, "resource" character varying(100) NOT NULL, "recordId" character varying(36) NOT NULL, "field" character varying(100) NOT NULL, "name" character varying(255) NOT NULL, "mimeType" character varying(120) NOT NULL, "size" integer NOT NULL, "stagingKey" character varying(512) NOT NULL, "key" character varying(512) NOT NULL, "status" character varying(10) NOT NULL, "expiresAt" TIMESTAMP NOT NULL, "createdAt" TIMESTAMP NOT NULL DEFAULT now(), CONSTRAINT "PK_9407909ac91dda6dae65f66393b" PRIMARY KEY ("id"));
CREATE INDEX "IDX_551a96e066bfd89ef803c3be6c" ON "cms_attachments" ("resource", "recordId", "status") ;
CREATE INDEX "IDX_d825fb8ce90d0a0cd08311e593" ON "cms_attachments" ("status", "expiresAt") ;
CREATE TABLE "admin_credentials" ("userId" character varying(36) NOT NULL, "passwordHash" character varying(256) NOT NULL, CONSTRAINT "PK_abeb10e05252bf7ef95c613920c" PRIMARY KEY ("userId"));
CREATE TABLE "admin_sessions" ("tokenHash" character varying(64) NOT NULL, "userId" character varying(36) NOT NULL, "expiresAt" TIMESTAMP NOT NULL, CONSTRAINT "PK_ca4c418a9411015771ead0487bd" PRIMARY KEY ("tokenHash"));
ALTER TABLE "users" ADD CONSTRAINT "FK_368e146b785b574f42ae9e53d5e" FOREIGN KEY ("roleId") REFERENCES "roles"("id") ON DELETE RESTRICT ON UPDATE NO ACTION;
